vec4 hash(vec4 p4)
{
    p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}
vec4 l (vec3 p) {
    vec3 c = (ceil(p.xyz));
    vec3 f = (floor(p.xyz));
    vec4 _000 = hash(vec4(c,1));
    vec4 _001 = hash(vec4(c.xy,f.z,1));
    vec4 _010 = hash(vec4(c.x,f.y,c.z,1));
    vec4 _011 = hash(vec4(c.x,f.y,f.z,1));
    vec4 _100 = hash(vec4(f.x,c.y,c.z,1));
    vec4 _101 = hash(vec4(f.x,c.y,f.z,1));
    vec4 _110 = hash(vec4(f.x,f.y,c.z,1));
    vec4 _111 = hash(vec4(f.x,f.y,f.z,1));
    vec4 _00 = mix(_001,_000,fract(p.z));
    vec4 _01 = mix(_011,_010,fract(p.z));
    vec4 _10 = mix(_101,_100,fract(p.z));
    vec4 _11 = mix(_111,_110,fract(p.z));
    vec4 _0 = mix(_01,_00,fract(p.y));
    vec4 _1 = mix(_11,_10,fract(p.y));
    return mix(_1,_0,fract(p.x));
}
